package cn.xinian.app;

import android.content.*;
import android.net.Uri;
import android.provider.MediaStore;
import android.media.*;
import java.io.*;
import java.net.HttpURLConnection;
import java.nio.ByteBuffer;

final class Saver {
  interface Progress {void update(String text);boolean cancelled();}
  static void check(Progress p) throws IOException{if(p.cancelled())throw new IOException("下载已取消");}
  static void fetch(String url,String ref,File output,Progress p) throws Exception{HttpURLConnection c=Network.open(url,true,ref);try(InputStream in=c.getInputStream();OutputStream out=new FileOutputStream(output)){String type=c.getContentType();if(type!=null&&(type.contains("text")||type.contains("json")))throw new IOException("平台返回了验证页面，请重新解析");long total=c.getContentLengthLong(),size=0,last=0;byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1){check(p);out.write(b,0,n);size+=n;if(size>1024L*1024*1024)throw new IOException("试用版单个文件暂限 1GB");if(System.currentTimeMillis()-last>500){last=System.currentTimeMillis();p.update("正在下载 · "+(size/1048576)+" MB"+(total>0?" / "+(total/1048576)+" MB":""));}}if(size==0)throw new IOException("下载文件为空");}finally{c.disconnect();}}
  static void fetchChoices(java.util.List<String> choices,String fallback,String ref,File output,Progress p) throws Exception {java.util.List<String> urls=choices.isEmpty()?java.util.Collections.singletonList(fallback):choices;Exception last=null;for(int i=0;i<urls.size();i++){check(p);try{if(i>0)p.update("正在尝试备用线路…");fetch(urls.get(i),ref,output,p);return;}catch(Exception e){last=e;check(p);}}throw last==null?new IOException("没有可用下载线路"):last;}
  static void mux(File video,File audio,File dest,Progress p) throws Exception{MediaExtractor v=new MediaExtractor(),a=new MediaExtractor();MediaMuxer m=null;boolean started=false;try{v.setDataSource(video.getPath());a.setDataSource(audio.getPath());int vi=track(v,"video/"),ai=track(a,"audio/");if(vi<0||ai<0)throw new IOException("手机无法识别该音视频格式");m=new MediaMuxer(dest.getPath(),MediaMuxer.OutputFormat.MUXER_OUTPUT_MPEG_4);int vt=m.addTrack(v.getTrackFormat(vi)),at=m.addTrack(a.getTrackFormat(ai));v.selectTrack(vi);a.selectTrack(ai);m.start();started=true;copy(v,m,vt,p);copy(a,m,at,p);m.stop();started=false;}finally{if(m!=null){if(started)try{m.stop();}catch(Exception ignored){}m.release();}v.release();a.release();}}
  static int track(MediaExtractor e,String prefix){for(int i=0;i<e.getTrackCount();i++)if(e.getTrackFormat(i).getString(MediaFormat.KEY_MIME).startsWith(prefix))return i;return -1;}
  static void copy(MediaExtractor e,MediaMuxer m,int target,Progress p) throws Exception {ByteBuffer b=ByteBuffer.allocateDirect(4*1024*1024);MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();while(true){check(p);b.clear();long needed=e.getSampleSize();if(needed>b.capacity()){if(needed>32*1024*1024)throw new IOException("视频帧过大");b=ByteBuffer.allocateDirect((int)needed);}int n=e.readSampleData(b,0);if(n<0)break;info.set(0,n,e.getSampleTime(),e.getSampleFlags());m.writeSampleData(target,b,info);e.advance();}}
  static Uri save(Context context,Media.Asset asset,String title,Progress p) throws Exception {File dir=new File(context.getCacheDir(),"job-"+java.util.UUID.randomUUID());if(!dir.mkdirs())throw new IOException("无法创建临时文件，请检查手机空间");File v=new File(dir,"video"),a=new File(dir,"audio"),out=v;Uri result=null;try{fetchChoices(asset.urls,asset.url,asset.referer,v,p);if(!asset.audio.isEmpty()){p.update("正在获取声音…");fetchChoices(asset.audioUrls,asset.audio,asset.referer,a,p);p.update("正在手机上合并声音与画面…");out=new File(dir,"merged.mp4");mux(v,a,out,p);}check(p);p.update("正在保存…");boolean image=asset.mime.startsWith("image/");ContentValues values=new ContentValues();String name=(title+"-"+asset.label).replaceAll("[\\\\/:*?\"<>|\\p{Cntrl}]","_");if(name.length()>70)name=name.substring(0,70);values.put(MediaStore.MediaColumns.DISPLAY_NAME,name+"-"+System.currentTimeMillis()+"."+asset.extension);values.put(MediaStore.MediaColumns.MIME_TYPE,asset.mime);values.put(MediaStore.MediaColumns.RELATIVE_PATH,image?"Pictures/惜年":"Movies/惜年");values.put(MediaStore.MediaColumns.IS_PENDING,1);ContentResolver cr=context.getContentResolver();result=cr.insert(image?MediaStore.Images.Media.EXTERNAL_CONTENT_URI:MediaStore.Video.Media.EXTERNAL_CONTENT_URI,values);if(result==null)throw new IOException("相册无法创建文件");try(InputStream in=new FileInputStream(out);OutputStream dest=cr.openOutputStream(result)){if(dest==null)throw new IOException("相册无法写入");byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1){check(p);dest.write(b,0,n);}}values.clear();values.put(MediaStore.MediaColumns.IS_PENDING,0);cr.update(result,values,null,null);return result;}catch(Exception e){if(result!=null)context.getContentResolver().delete(result,null,null);throw e;}finally{for(File f:new File[]{v,a,new File(dir,"merged.mp4")})f.delete();dir.delete();}}
}
